command:
set -eu
client_cfg=/root/.mariadb-galera-client.cnf
printf 'node=%s ip=%s service=' "$NODE_NAME" "$NODE_IP"
systemctl is-active mariadb
printf 'enabled='
systemctl is-enabled mariadb
mariadb --defaults-extra-file="$client_cfg" --host="$NODE_IP" --batch --skip-column-names <<'ANTRIEB_SQL'
SELECT CONCAT('server=',@@hostname);
SHOW GLOBAL STATUS WHERE Variable_name IN ('wsrep_cluster_size','wsrep_cluster_status','wsrep_connected','wsrep_incoming_addresses','wsrep_local_state_comment','wsrep_ready');
SELECT CONCAT('row_count=',COUNT(*)) FROM galera_benchmark.member_writes;
SELECT marker,source_node FROM galera_benchmark.member_writes ORDER BY marker;
ANTRIEB_SQL

